<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Admin dashboard';$basePath='../';$counts=[];foreach(['books'=>'SELECT COUNT(*) FROM books','members'=>'SELECT COUNT(*) FROM members','active'=>'SELECT COUNT(*) FROM loans WHERE status="issued"','overdue'=>'SELECT COUNT(*) FROM loans WHERE status="issued" AND due_date<CURDATE()','fines'=>'SELECT COALESCE(SUM(amount),0) FROM fines WHERE status="unpaid"'] as $k=>$q)$counts[$k]=$pdo->query($q)->fetchColumn();$recent=$pdo->query('SELECT l.*,m.name member_name,b.title FROM loans l JOIN members m ON m.id=l.member_id JOIN books b ON b.id=l.book_id ORDER BY l.id DESC LIMIT 7')->fetchAll();require __DIR__.'/../includes/layout_top.php';?>
<div class="welcome"><div><span class="eyebrow light">LIBRARY OVERVIEW</span><h2>Good day, <?=e(current_user()['name'])?></h2><p>Manage your catalogue, members and circulation from one place.</p></div><div class="welcome-icon">▤</div></div><div class="stats-grid"><div class="stat"><span>Total books</span><b><?=$counts['books']?></b><small>Titles in catalogue</small></div><div class="stat"><span>Members</span><b><?=$counts['members']?></b><small>Registered accounts</small></div><div class="stat"><span>Currently issued</span><b><?=$counts['active']?></b><small>Active loans</small></div><div class="stat"><span>Overdue</span><b class="text-danger"><?=$counts['overdue']?></b><small>Require attention</small></div><div class="stat"><span>Unpaid fines</span><b><?=money($counts['fines'])?></b><small>Recorded balance</small></div></div><div class="panel"><div class="panel-head"><div><h3>Recent circulation</h3><p>Latest book issue and return activity.</p></div><a class="btn small" href="loans.php">Manage loans</a></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Book</th><th>Issue date</th><th>Due date</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['member_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['issue_date'])?></td><td><?=e($r['due_date'])?></td><td><span class="pill <?=$r['status']==='issued'?'warning':'success'?>"><?=$r['status']?></span></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5" class="empty">No circulation records yet.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
